import {TASKS,getTask,initialState,isComplete,transition,stage,searchTasks} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M4 4h6a3 3 0 0 1 2 2 3 3 0 0 1 2-2h6v15h-6a3 3 0 0 0-2 2 3 3 0 0 0-2-2H4Zm8 2v15',leaf:'M19 4c-10-1-16 5-12 11 6 6 13-1 12-11ZM4 21 15 9',heart:'M20.5 4.6a5.5 5.5 0 0 0-8.5 1 5.5 5.5 0 0 0-8.5 7L12 21l8.5-8.4a5.5 5.5 0 0 0 0-8Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Zm-3 5v2a6 6 0 0 0 12 0v-2M12 18v4m-4 0h8',screen:'M3 4h18v13H3Zm5 17h8m-4-4v4m-4-11 4-4 4 4m-4-4v8',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4',file:'M5 3h9l5 5v13H5Zm9 0v6h5M8 13h8m-8 4h6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5Zm7 4v3',form:'M6 3h12v18H6Zm3 5h6m-6 4h6m-6 4h4',video:'M3 6h12v12H3Zm12 4 6-3v10l-6-3',link:'m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 2 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',search:'M20 20l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',check:'m5 12 4 4L19 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',sound:'M4 9h4l5-4v14l-5-4H4Zm12-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16',help:'M9 8a3 3 0 1 1 4 3c-1 .4-1 1-1 3m0 4v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',play:'m9 5 11 7-11 7Z',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',globe:'M2 12h20M12 2c6 7 6 13 0 20-6-7-6-13 0-20Zm10 10a10 10 0 1 1-20 0 10 10 0 0 1 20 0',clock:'M12 7v5l3 2m7-2a10 10 0 1 1-20 0 10 10 0 0 1 20 0',people:'M16 21v-3a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v3m14-7a4 4 0 0 1 6 4v3M12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4-4a4 4 0 0 1 0 8',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',camera:'M3 7h4l2-3h6l2 3h4v13H3Zm13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',stop:'M6 6h12v12H6Z',replay:'M3 10a9 9 0 1 1 2 8M3 3v7h7',pause:'M8 4v16m8-16v16',star:'m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1Z',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2m-3 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
function icon(n,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;}
function art(){return `<svg viewBox="0 0 260 235" fill="none" aria-hidden="true"><ellipse cx="131" cy="208" rx="91" ry="12" fill="#dcd2ed"/><g class="float"><rect x="50" y="53" width="154" height="116" rx="16" fill="#fffdf9" stroke="#bba9d4" stroke-width="2" transform="rotate(-7 127 110)"/><path d="M72 83h58" stroke="#d8cce9" stroke-width="7" stroke-linecap="round"/><rect x="71" y="99" width="105" height="41" rx="9" fill="#f0eaf8"/><path d="m106 119 10 9 20-22" stroke="#7958ab" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><path d="M62 172h137l16 13a5 5 0 0 1-4 8H48a5 5 0 0 1-4-8l18-13Z" fill="#aa94c8"/><rect x="101" y="176" width="51" height="5" rx="2.5" fill="#cfbfe2"/></g><g class="float2"><rect x="173" y="27" width="54" height="55" rx="17" fill="#d5e5cb" stroke="#a9bfa0" stroke-width="1.5" transform="rotate(12 200 55)"/><path d="m186 54 9 9 15-18" stroke="#628451" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></g><g class="float"><rect x="23" y="126" width="49" height="49" rx="15" fill="#f6dfb4" stroke="#dbc091" transform="rotate(-15 48 150)"/><path d="M41 145c1-9 12-8 13 0 1 5-5 6-5 10m0 6v1" stroke="#ae8542" stroke-width="3" stroke-linecap="round"/></g><path d="m39 42 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z" fill="#b09bc9"/><circle cx="225" cy="150" r="5" fill="#c2d4b6"/><circle cx="107" cy="24" r="3" fill="#b7a2d0"/><path d="m230 99 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z" fill="#d7bb8f"/></svg>`;}
function person(){return `<svg class="person-art" viewBox="0 0 150 190" aria-hidden="true"><path d="M20 190v-31a55 55 0 0 1 110 0v31" fill="#a08bba"/><path d="M59 115h32v34c-10 12-22 12-32 0" fill="#d4a187"/><ellipse cx="75" cy="79" rx="38" ry="47" fill="#dfb094"/><path d="M36 73c-5-47 56-69 79-31 5 8 5 20 1 31-10-2-15-22-18-26-15 13-38 17-62 26Z" fill="#4b3d43"/><circle cx="61" cy="81" r="2" fill="#4c3d40"/><circle cx="89" cy="81" r="2" fill="#4c3d40"/><path d="M64 101q11 9 22 0" stroke="#a76558" stroke-width="2" fill="none" stroke-linecap="round"/></svg>`;}
const translations={home:['Home','Shuru karein'],library:['Explore tasks','Kaam talash karein'],progress:['My learning','Meri seekh'],helper:['Help someone','Kisi ko sikhayein'],hello:['A LITTLE HELP. A LOT MORE CONFIDENCE.','THORI MADAD. ZYADA BHAROSA.'],heading:['Everyday technology.','Rozmarra ki technology.'],pace:['At your pace.','Aapki raftaar se.'],sub:['A safe place to try, understand, and do it yourself. One small step at a time.','Yahan aaram se azmayein, samjhein, aur khud karein. Ek waqt mein ek qadam.'],placeholder:['What would you like to do?','Aap kya karna chahte hain?'],popular:['A good place to start','Yahan se shuru karein'],all:['Explore all tasks','Sab kaam dekhein'],practice:['Safe practice','Mehfooz mashq'],start:['Let’s get started','Shuru karein'],noRush:['No rush. No judgement.','Na jaldi. Na jhijhak.']};
let state={page:'home',lang:'en',category:'All topics',query:'',large:false,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,save:false,records:[],lesson:null,helperTask:'share',helperName:'',helperNote:'',helperReady:false,context:'practice',lastFocus:null};
try{const saved=JSON.parse(localStorage.getItem('samajh-progress')||'null');if(saved?.consent===true){state.save=true;state.records=Array.isArray(saved.records)?saved.records.filter(r=>getTask(r.id)).slice(-100):[];}}catch{}
const tr=k=>translations[k]?.[state.lang==='ur'?1:0]||k;
const title=t=>state.lang==='ur'?t.ur:t.title;
function save(){try{if(state.save)localStorage.setItem('samajh-progress',JSON.stringify({consent:true,records:state.records.slice(-100)}));else localStorage.removeItem('samajh-progress');}catch{toast('Your browser could not save progress. You can still practise.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
const navItems=[['home','home'],['library','book'],['progress','leaf'],['helper','heart']];
function nav(mobile=false){return navItems.map(([id,ico])=>`<button class="${mobile?'':'nav-btn '}${state.page===id?'active':''}" data-nav="${id}" ${state.page===id?'aria-current="page"':''}>${icon(ico,20)}<span>${tr(id)}</span></button>`).join('');}
function render(focus=true){document.documentElement.lang=state.lang==='ur'?'ur-Latn':'en';document.body.classList.toggle('text-lg',state.large);document.body.classList.toggle('motion-off',!state.motion);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#home" class="brand" aria-label="Samajh home"><img src="assets/favicon.svg" alt="">samajh<span class="dot">.</span></a><p class="brand-note">Small steps. Real confidence.</p><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="side-bottom"><div class="side-note">${icon('leaf',24)}<strong>You don’t have to know it all.</strong>Just take the next small step. We’ll be right here.</div><button class="nav-btn" data-modal="help">${icon('help')}<span>How Samajh works</span></button><div class="side-footer">Made for people, not experts.</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your space ${icon('arrow',13)} <span>${state.page==='lesson'?'Practice':state.page==='result'?'Your progress':tr(state.page)}</span></div><a href="#home" class="brand mobile-brand"><img src="assets/favicon.svg" alt="">samajh<span class="dot">.</span></a><div class="toolbar"><button class="tool-btn" data-action="language" aria-label="Switch language: ${state.lang==='en'?'Roman Urdu':'English'}">${icon('globe',17)}<span>${state.lang==='en'?'English':'Roman Urdu'}</span></button><button class="tool-btn" data-action="size" aria-label="${state.large?'Use standard':'Use larger'} text" aria-pressed="${state.large}"><strong>Aa</strong><span>Text size</span></button><button class="tool-btn" data-modal="settings" aria-label="Accessibility and privacy settings">${icon('settings',18)}</button><div class="avatar" title="Guest learner">You</div></div></header><main class="content" id="main" tabindex="-1">${content()}</main></div></div><nav class="mobile-nav" aria-label="Main navigation">${nav(true)}</nav><button class="help-bubble" data-modal="help" aria-label="Get help">${icon('help',24)}</button>`;bind();if(focus){$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function content(){switch(state.page){case 'library':return library();case 'progress':return progress();case 'helper':return helper();case 'lesson':return lesson();case 'result':return result();default:return home();}}
function searchBox(home=false){return `<form id="search-form" class="search-wrap ${home?'':'library-search'}" role="search"><label for="task-search" class="skip-link">Search for a task</label>${icon('search',21)}<input id="task-search" class="search-input" type="search" value="${esc(state.query)}" placeholder="${tr('placeholder')}" autocomplete="off"><button class="search-go" aria-label="Find a task">${icon('arrow',20)}</button></form>`;}
function chips(){return `<div class="categories" aria-label="Filter topics">${['All topics','Meetings','Files & forms','Privacy'].map((c,i)=>`<button class="chip ${state.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${state.category===c}">${i?icon(['','video','file','shield'][i],14):''}${c}</button>`).join('')}</div>`;}
function cards(list){if(!list.length)return `<div class="empty full-width">${icon('search',35)}<h3>Let’s find another way.</h3><p>We don’t have a verified task for that yet. Try “microphone”, “PDF”, or “sharing”. Samajh only teaches the tasks listed here.</p><button class="btn btn-subtle" data-action="clear-search">Show all tasks</button></div>`;return list.map(t=>`<button class="task-card" data-task="${t.id}"><div class="card-top"><span class="icon-tile ${t.color}">${icon(t.icon,24)}</span><span class="time">${t.time}</span></div><h3>${title(t)}</h3><p>${t.description}</p><div class="card-footer"><span class="tiny-badge">${icon('leaf',13)}Interactive practice</span><span class="card-arrow">${icon('arrow',16)}</span></div></button>`).join('');}
function home(){const list=searchTasks('',state.category).slice(0,4);return `<div class="intro-line"><span class="eyebrow">Your next small step starts here</span><span class="gentle-pill"><span class="status-dot"></span>${tr('noRush')}</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">${tr('hello')}</div><h1>${tr('heading')}<br><span style="color:var(--purple)">${tr('pace')}</span></h1><p>${tr('sub')}</p>${searchBox(true)}<p class="micro search-hint">Try “share my screen” or “send a PDF”</p></div><div class="hero-art">${art()}</div></section><div class="main-grid"><section><div class="section-head"><h2>${tr('popular')}</h2><button class="link-btn" data-nav="library">${tr('all')}${icon('arrow',15)}</button></div>${chips()}<div class="cards">${cards(list)}</div></section><aside class="right-rail"><div class="side-panel"><div class="eyebrow">A little practice goes a long way</div>${icon('leaf',28)}<h3>You can do this.<br>Really.</h3><p>You don’t need to learn everything. Start with one thing you want to do.</p><div class="mini-steps"><div class="mini-step"><span>1</span>Choose an everyday task</div><div class="mini-step"><span>2</span>Try it in a safe space</div><div class="mini-step"><span>3</span>Give it a go on your own</div></div><button class="btn btn-green" data-task="mic">Try a small step ${icon('arrow',17)}</button></div><div class="watch-card"><div class="video-thumb"><svg class="vid-art" viewBox="0 0 210 130" aria-hidden="true"><rect x="46" y="26" width="120" height="75" rx="8" fill="#fffaf4" stroke="#dcc5aa"/><rect x="56" y="37" width="100" height="51" rx="4" fill="#ead8c4"/><path d="M40 103h132l8 6H32Z" fill="#c6a789"/><circle cx="178" cy="28" r="13" fill="#e4c896"/><path d="m20 56 5 8 8 3-8 3-5 8-3-8-8-3 8-3Z" fill="#cab1d9"/></svg><button class="play" data-modal="video" aria-label="Watch how Samajh works">${icon('play',18)}</button></div><div class="watch-content"><strong>A quick hello from Samajh</strong><p>Watch our 12-second introduction ${icon('arrow',12)}</p></div></div></aside></div><div class="reassurance"><span>${icon('shield',15)}No real accounts needed</span><span>${icon('heart',15)}Mistakes are welcome</span><span>${icon('clock',15)}Always at your pace</span></div>${footer()}`;}
function library(){const list=searchTasks(state.query,state.category);return `<div class="page-title"><span class="eyebrow">A little more independent, every day</span><h1 style="margin-top:12px">What would you like to do?</h1><p>Choose a task. We’ll help you understand it, then practise it safely.</p></div>${searchBox()}${chips()}<div class="section-head"><p class="micro">${list.length} supported ${list.length===1?'task':'tasks'} · fictional practice, no real account access</p><button class="link-btn" data-modal="context">Using Zoom or Google Meet? ${icon('help',15)}</button></div><div class="cards catalog-grid">${cards(list)}</div>${footer()}`;}
function footer(){return `<footer class="footer"><span>samajh. · Small steps. Real confidence.</span><div><button data-modal="privacy">Your privacy</button> · <button data-modal="about">About this prototype</button></div></footer>`;}
function progress(){const records=state.records;const unique=new Set(records.map(r=>r.id)).size;const indep=records.filter(r=>r.hints===0&&r.transfer).length;return `<div class="page-title"><span class="eyebrow">Every small step counts</span><h1 style="margin-top:12px">Look how far you’ve come.</h1><p>This is your learning space. There’s no score to chase.</p></div><div class="progress-summary"><div class="stat-box"><span>Different tasks practised</span><strong class="big-number">${unique}</strong><p class="micro">Out of ${TASKS.length} supported tasks</p></div><div class="stat-box"><span>New-layout attempts without hints</span><strong class="big-number">${indep}</strong><p class="micro">A step toward independence</p></div><div class="stat-box"><span>Progress storage</span><strong>${state.save?'Saved on this device':'This visit only'}</strong><button class="link-btn" data-modal="settings">Manage your choices ${icon('arrow',14)}</button></div></div>${!records.length?`<div class="empty">${icon('leaf',40)}<h2 style="margin-top:18px">Your first small step is waiting.</h2><p>Complete a practice task and it will appear here. There’s no hurry.</p><button class="btn btn-primary" data-nav="library">Find my first task ${icon('arrow',18)}</button></div>`:`<div class="section-head"><h2>Your practice moments</h2><button class="link-btn" data-action="download-progress">Download summary ${icon('download',16)}</button></div><div class="learning-list">${[...records].reverse().map(r=>{const t=getTask(r.id);return `<div class="learning-item"><span class="icon-tile ${t.color}">${icon(t.icon,22)}</span><div><h3>${title(t)}</h3><p>${r.transfer?'Different layout':'Guided practice'} · ${r.hints===0?'No hints requested':`${r.hints} hints requested`} · ${new Date(r.at).toLocaleDateString()}</p></div><button class="btn btn-subtle" data-task="${t.id}">Try again ${icon('replay',16)}</button></div>`;}).join('')}</div>`}<div class="notice">${icon('shield',21)}<span>Finishing a practice task shows what you did here. It does not certify that you can use every real app. You can always ask for help.</span></div>${records.length?`<button class="link-btn" style="margin-top:20px" data-modal="erase">Clear my learning history</button>`:''}${footer()}`;}
function helper(){return `<div class="page-title"><span class="eyebrow">A familiar voice makes a difference</span><h1 style="margin-top:12px">A little help, made personal.</h1><p>Choose a supported task and leave a kind note for someone you’re helping.</p></div><div class="helper-grid"><section class="white-panel"><h2>Make a practice guide</h2><p>Your note appears alongside our reviewed task. It never changes the task’s safety rules.</p><form id="helper-form"><label class="form-label" for="helper-name">Who is this for? <span class="micro">(optional first name)</span></label><input id="helper-name" class="text-field" maxlength="30" placeholder="For example, Ammi" value="${esc(state.helperName)}"><label class="form-label" for="helper-task">What would you like to practise?</label><select id="helper-task" class="text-field">${TASKS.map(t=>`<option value="${t.id}" ${t.id===state.helperTask?'selected':''}>${t.title}</option>`).join('')}</select><label class="form-label" for="helper-note">A reassuring note</label><textarea id="helper-note" class="text-field" maxlength="240" placeholder="Take your time. Try it here first, and I’m here if you need me.">${esc(state.helperNote)}</textarea><p class="micro" style="margin:10px 0 20px">Please don’t include passwords, phone numbers, or private details. Notes stay in this visit unless you choose to copy a link.</p><button class="btn btn-primary full" type="submit">Preview the guide ${icon('arrow',18)}</button></form></section><section class="white-panel"><span class="eyebrow">${state.helperReady?'Your guide is ready':'The learner’s view'}</span><div class="helper-preview"><span class="icon-tile">${icon(getTask(state.helperTask).icon,25)}</span><h2 style="margin-top:18px">${state.helperReady&&state.helperName?`${esc(state.helperName)}, let’s take a small step.`:'You don’t have to figure it out alone.'}</h2><p>${state.helperReady?esc(state.helperNote||'Take your time. You can always ask for a hint.'):'A small, personal message. One clear task. Space to try, without the pressure.'}</p><div class="pill-small" style="display:inline-block">${getTask(state.helperTask).title}</div></div><button class="btn btn-subtle full" data-action="helper-start" ${state.helperReady?'':'disabled'}>Open this practice guide ${icon('arrow',18)}</button><button class="btn btn-secondary full" style="margin-top:10px" data-action="copy-guide" ${state.helperReady?'':'disabled'}>${icon('link',17)}Copy learner link</button><p class="micro" style="margin-top:15px">The link includes the optional first name and note. Anyone with it can read them. It opens on this site; site access rules still apply.</p></section></div>${footer()}`;}
function startTask(id,transfer=false){if(!getTask(id))return;const note=state.helperReady&&state.helperTask===id?state.helperNote:'';state.lesson={id,transfer,s:initialState(id,transfer),hints:0,showHint:false,demonstrated:false,note,feedback:'',explanation:''};state.page='lesson';state.query='';if(!location.hash.startsWith('#guide='))history.replaceState(null,'',location.pathname+'#task='+id);render();}
function scene(s,blur=false){return `<div class="call-scene ${blur?'blur':''}"><div class="background-shapes"></div>${person()}<span class="name-label">You · sample preview</span><span class="call-state">${s}</span></div>`;}
function control(action,label,ico,off=false,value='',selected=false){return `<button class="control-btn ${off?'off':''} ${selected?'selected':''}" data-do="${action}" ${value?`data-value="${esc(value)}"`:''}>${icon(ico,22)}<span>${label}</span></button>`;}
function practiceSurface(t,l){const s=l.s;let inner='';const alt=l.transfer;
 switch(t.id){
 case 'mic':inner=scene(s.permission&&!s.muted?'Voice is on':'They cannot hear you')+`<div class="call-controls" style="${alt?'flex-direction:row-reverse;':''}">${control('mute',s.muted?(alt?'Enable voice':'Unmute'):'Mute','mic',s.muted)}${control('settings',alt?'Audio access':'Permissions','settings',!s.permission)}</div>${s.settings?`<div class="setting-row"><div><strong>Microphone permission</strong><small>Allow this fictional meeting to use a microphone.</small></div><button class="switch" role="switch" aria-checked="${s.permission}" aria-label="Microphone permission" data-do="permission"><span></span></button></div>`:''}<div class="sim-message ${isComplete(t.id,s)?'success':''}" role="status">${!s.permission?'Microphone access is blocked in this practice app. Unmuting alone will not enable your voice.':s.muted?'Your microphone is muted. Look for the microphone control.':'The other person can hear you in this simulation. Permission is allowed and mute is off.'}</div>`;break;
 case 'share':inner=`<div class="share-preview"><div>${s.sharing?`${icon('screen',30)}<p>Presentation window is shared</p><p class="micro">Other sample windows are not visible.</p>`:s.stopped?`${icon('check',35)}<p>Screen sharing has stopped.</p>`:`<div class="sample-window">${icon('file',28)}<p>Your presentation</p><p class="micro">A window you can share safely</p></div>`}</div></div>${!s.picker?`<button class="btn btn-primary full" data-do="picker">${icon('screen',19)}${alt?'Present something':'Share screen'}</button>`:s.sharing?`<button class="btn btn-subtle full" data-do="stop">${icon('stop',18)}Stop sharing</button>`:!s.stopped?`<p style="font-size:15px">Choose what the other person can see:</p><div class="choice-grid">${['screen','window','tab'].map(x=>`<button class="choice-tile ${s.surface===x?'selected':''}" data-do="surface" data-value="${x}">${icon(x==='screen'?'screen':x==='window'?'file':'link',22)}${x==='screen'?'Entire screen':x==='window'?'One window':'Browser tab'}</button>`).join('')}</div>${s.surface==='screen'?`<div class="safe-hint">An entire screen can reveal other apps and notifications. For this task, choose just the presentation window.</div>`:''}${s.surface==='tab'?`<div class="sim-message">A browser tab can be useful, but this presentation is a separate window. Choose One window for this task.</div>`:''}${s.surface==='window'?`<button class="recipient ${s.selected?'selected':''}" data-do="select">${icon('file',24)}<div>Presentation.pdf<div class="sub">Only this sample window</div></div>${s.selected?`<span class="check">${icon('check',22)}</span>`:''}</button><button class="btn btn-primary full" style="margin-top:14px" data-do="share" ${s.selected?'':'disabled'}>Share selected window</button>`:''}`:''}`;break;
 case 'blur':inner=scene(s.blur?'Blur preview':'Background visible',s.blur)+`<div class="call-controls">${control('effects',alt?'Appearance':'Effects','sparkles',false,'',s.effects)}</div>${s.effects?`<div class="choice-row"><button class="btn ${s.blur?'btn-secondary':'btn-subtle'}" data-do="blur" data-value="none">Original</button><button class="btn ${s.blur?'btn-subtle':'btn-secondary'}" data-do="blur" data-value="blur">${icon('sparkles',18)}Blur</button></div><button class="btn btn-primary full" style="margin-top:14px" data-do="apply" ${s.blur?'':'disabled'}>Apply this background</button>`:''}<p class="inline-label">A fictional preview. Samajh does not access your camera.</p>`;break;
 case 'pdf':inner=`<div class="share-preview"><div>${icon('file',42)}<h3 style="margin-top:12px">${alt?'Workshop notes':'Family presentation'}</h3><p class="micro">Fictional document · no upload needed</p></div></div>${!s.exported?`<p style="font-size:15px">Choose an export format:</p><div class="choice-row"><button class="btn btn-subtle" data-do="export" data-value="pdf">PDF document</button><button class="btn btn-secondary" data-do="export" data-value="link">Share a link</button></div>`:!s.downloads?`<div class="sim-message success">A sample PDF copy is ready. Where will you find a downloaded file?</div><button class="btn btn-subtle full" style="margin-top:15px" data-do="downloads">${icon('download',18)}Open Downloads</button>`:!s.attached?`<div class="sim-message">Downloads</div><button class="recipient" data-do="attach">${icon('file',25)}<div>presentation.pdf<div class="sub">Select this sample file to attach it</div></div>${icon('arrow',17)}</button>`:`<div class="sim-message">To: Sana (fictional recipient)</div><div class="recipient">${icon('file',22)}presentation.pdf <span class="pill-small">Attached</span></div><button class="btn btn-primary full" style="margin-top:15px" data-do="send" ${s.sent?'disabled':''}>${s.sent?'Practice message sent':'Send practice message'}${icon('mail',18)}</button>`}`;break;
 case 'access':inner=`<div class="row">${icon('lock',25)}<div><strong>${alt?'Workshop notes.pdf':'Family photo.jpg'}</strong><p class="micro">Who should be able to open it?</p></div></div>${[['sana','Only Sana','One chosen person','S'],['group','Family group','All 6 sample members','6'],['anyone','Anyone with the link','People who receive or forward the link','∞']].map(([v,name,desc,a])=>`<button class="recipient ${s.audience===v?'selected':''}" data-do="audience" data-value="${v}"><span class="avatar">${a}</span><div>${name}<div class="sub">${desc}</div></div>${s.audience===v?`<span class="check">${icon('check',20)}</span>`:''}</button>`).join('')}<button class="btn btn-subtle full" data-do="view" style="margin-top:16px">${icon('people',18)}See the recipient view</button>${s.viewed?`<div class="sim-message ${s.audience==='sana'?'success':''}"><strong>${s.audience==='sana'?'Sana can open it. Other sample people cannot.':s.audience==='group'?'All six group members can open it.':'Anyone who gets the link can open it.'}</strong><br>${s.audience==='sana'?'This matches your goal: Sana only.':'Your goal is to share with Sana only. Try restricting access.'}</div>${s.audience==='sana'?`<button class="btn btn-primary full" data-do="confirm" style="margin-top:14px" ${s.confirmed?'disabled':''}>${s.confirmed?'Restricted access confirmed':'Confirm: only Sana'}</button>`:''}`:''}`;break;
 case 'form':inner=`<h3>${alt?'Workshop registration':'Community class registration'}</h3><p class="micro">Use the sample details. This is not a real registration.</p><label class="form-label" for="sim-email">Sample email</label><input id="sim-email" type="text" inputmode="email" class="text-field" value="${esc(s.email)}" aria-invalid="${s.errors&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)}" ${s.errors?'aria-describedby="email-error"':''}>${s.errors?`<p id="email-error" class="field-error">${!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)?'Add a complete email, for example sana@example.com.':''}</p>`:''}<label class="form-label" for="sim-city">City</label><select id="sim-city" class="text-field" aria-invalid="${s.errors&&!s.city}"><option value="">Choose a city</option>${['Karachi','Lahore','Islamabad'].map(x=>`<option ${s.city===x?'selected':''}>${x}</option>`).join('')}</select>${s.errors&&!s.city?`<p class="field-error">Choose a city to continue.</p>`:''}<button class="btn btn-primary full" style="margin-top:23px" data-do="submit" ${s.submitted?'disabled':''}>${s.submitted?'Registration confirmed':'Submit sample form'}${icon('arrow',18)}</button>${s.submitted?`<div class="sim-message success" role="status">Confirmation S-1042. Your sample registration is complete.</div>`:''}`;break;
 case 'join':inner=scene(`${s.camera?'Camera on':'Camera off'} · ${s.muted?'Muted':'Microphone on'}`)+`<div class="call-controls">${control('camera',s.camera?'Camera on':'Camera off','camera',!s.camera)}${control('mute',s.muted?'Muted':'Microphone on','mic',s.muted)}</div><div class="sim-message">Your goal: enter quietly, with camera off and microphone muted.</div><button class="btn btn-primary full" style="margin-top:15px" data-do="join" ${s.joined?'disabled':''}>${s.joined?'You joined the practice call':alt?'Enter call':'Join meeting'}</button>`;break;
 case 'copy':inner=`<div class="share-preview"><div>${icon('file',40)}<h3 style="margin-top:12px">${alt?'Class notes':'Presentation'}</h3><p class="micro">You want to send a separate copy.</p></div></div><div class="choice-row"><button class="btn ${s.choice==='file'?'btn-subtle':'btn-secondary'}" data-do="choice" data-value="file">${icon('file',18)}PDF attachment</button><button class="btn ${s.choice==='link'?'btn-subtle':'btn-secondary'}" data-do="choice" data-value="link">${icon('link',18)}Online link</button></div>${s.choice?`<label for="copy-answer" class="form-label">If Sana saves the PDF, then you remove online access...</label><select id="copy-answer" class="text-field"><option value="">What happens to her saved copy?</option><option value="keeps" ${s.answer==='keeps'?'selected':''}>Her saved copy stays with her</option><option value="erased" ${s.answer==='erased'?'selected':''}>Her saved copy disappears</option></select><button class="btn btn-primary full" style="margin-top:15px" data-do="check">Check my understanding</button>${s.checked&&!isComplete(t.id,s)?`<div class="sim-message">An attachment is a separate copy, and a saved copy is not erased when online access changes. Try those choices.</div>`:''}`:''}`;break;
 }
 return inner;
}
function lesson(){const l=state.lesson,t=getTask(l.id),complete=isComplete(l.id,l.s),current=stage(l.id,l.s);return `<div class="lesson-top"><button class="back-btn" data-nav="library">${icon('back',17)}Back to tasks</button><span class="practice-tag">${icon('shield',14)}Practice only · nothing real changes</span></div><div class="lesson-head"><span class="eyebrow">${t.category} / ${l.transfer?'A different view':'Learn with me'}</span><h1 style="margin-top:11px">${title(t)}</h1><p>${l.transfer?'Same understanding. A slightly different screen. Take your time.':t.description}</p></div>${l.transfer?`<div class="transfer-banner">${icon('leaf',18)}Try this new layout in your own way. Help is always available; using it is okay.</div>`:''}${l.note?`<div class="helper-note"><strong>A note from your helper</strong><br>${esc(l.note)}</div>`:''}<div class="learning-grid"><aside class="coach"><div class="coach-eyebrow">${icon('sparkles',17)}Your gentle guide</div><h2>${t.goal}</h2><p>${l.transfer&&!l.showHint?'Look at the screen and decide your next step. You can ask for a clue whenever you need one.':t.why}</p>${!l.transfer||l.showHint?`<ol>${t.steps.map((s,i)=>`<li class="${current>i?'done':current===i?'current':''}"><span class="step-number">${current>i?icon('check',13):i+1}</span>${s}</li>`).join('')}</ol>`:''}${l.showHint?`<div class="helper-note">${t.hint}</div>`:''}<div class="coach-footer"><button class="btn btn-secondary" data-action="read">${icon('sound',18)}Read to me</button><button class="btn btn-subtle" data-action="hint">${icon('help',18)}${l.showHint?'Repeat the clue':'I need a clue'}</button><button class="btn btn-secondary" data-modal="walkthrough">${icon('play',16)}Show me first</button></div></aside><section><div class="sim ${l.transfer?'alternate':''}"><div class="sim-bar"><div class="row"><span class="window-dots"><i></i><i></i><i></i></span><span>${l.transfer?'Everyday workspace':'Samajh practice space'}</span></div><span>SIMULATION</span></div><div class="sim-body">${practiceSurface(t,l)}</div></div>${l.feedback?`<div class="sim-message" role="status">${esc(l.feedback)}</div>`:''}${complete?`<div class="success-panel" role="status">${icon('check',27)}<h3>${l.transfer?'You handled a different view.':'That’s a small step worth keeping.'}</h3><p>${t.why}</p><button class="btn btn-primary" data-action="complete">${l.transfer?'See my practice summary':'Try a different view'} ${icon('arrow',18)}</button></div>`:''}<div class="lesson-controls"><p class="micro">All names, calls, settings, and files here are fictional.<br>You’re practising the idea, not controlling a real app.</p><button class="back-btn" data-action="restart">${icon('replay',15)}Start this attempt again</button></div></section></div>${footer()}`;}
function result(){const l=state.lesson,t=getTask(l.id);return `<div class="result"><span class="eyebrow">One step closer to doing it yourself</span><div class="result-icon" style="margin-top:25px">${icon('leaf',44)}</div><h1>You made room for<br>a little more confidence.</h1><p>You practised <strong>${title(t).toLowerCase()}</strong> and tried a different view. You can come back whenever you need.</p><div class="result-stats"><div class="stat-box"><span>What you explored</span><strong>${t.concept}</strong><p class="micro">${l.demonstrated?'You also viewed a demonstration.':'A practical concept to use elsewhere.'}</p></div><div class="stat-box"><span>Your different-view attempt</span><strong>${l.hints?'With a little help':'Without requesting hints'}</strong><p class="micro">${l.hints?`${l.hints} hints or demonstrations requested.`:'An encouraging first step, not a mastery certificate.'}</p></div></div><div class="explain-card"><label for="reflection">Before you go: what would you check next time?</label><select class="text-field" id="reflection"><option value="">Choose a reminder for yourself</option><option>Check the visible result before assuming it worked</option><option>Check permissions separately from in-app controls</option><option>Check the audience before sharing</option><option>Ask for help when I am unsure</option></select><p class="micro" style="margin-top:10px">Reflection only. Your choice is not graded.</p></div><div class="result-actions"><button class="btn btn-primary" data-nav="library">Choose my next task ${icon('arrow',18)}</button><button class="btn btn-secondary" data-nav="progress">See my learning ${icon('leaf',18)}</button></div>${!state.save?`<div class="notice">${icon('shield',20)}<div>Your progress lasts for this visit. <button class="link-btn" data-modal="settings">Choose to remember it on this device</button></div></div>`:''}</div>${footer()}`;}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>startTask(b.dataset.task));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;render(false);});document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>modal(b.dataset.modal));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>doAction(b.dataset.do,b.dataset.value));
 $('#search-form')?.addEventListener('submit',e=>{e.preventDefault();state.query=$('#task-search').value.trim();state.category='All topics';state.page='library';render();});
 $('#helper-form')?.addEventListener('submit',e=>{e.preventDefault();state.helperTask=$('#helper-task').value;state.helperName=$('#helper-name').value.trim();state.helperNote=$('#helper-note').value.trim();state.helperReady=true;render(false);toast('Your practice guide is ready to preview.');});
 if($('#sim-email'))$('#sim-email').oninput=e=>{state.lesson.s=transition('form',state.lesson.s,'email',e.target.value);};
 if($('#sim-city'))$('#sim-city').onchange=e=>{state.lesson.s=transition('form',state.lesson.s,'city',e.target.value);};
 if($('#copy-answer'))$('#copy-answer').onchange=e=>{state.lesson.s=transition('copy',state.lesson.s,'answer',e.target.value);};
}
function navigate(page){if('speechSynthesis'in window)speechSynthesis.cancel();state.page=page;state.query='';state.category='All topics';history.replaceState(null,'',location.pathname+location.search+'#'+page);render();}
function doAction(a,v){const l=state.lesson;if(!l)return;const prev=l.s;l.s=transition(l.id,l.s,a,v);l.feedback='';if(l.id==='join'&&a==='join'&&!l.s.joined)l.feedback='Check the two controls first. For this task, turn the camera off and mute the microphone before joining.';if(l.id==='pdf'&&a==='export'&&v==='link')l.feedback='A link gives access to an online item. For this task, choose a PDF to create a separate file copy.';const pos=scrollY;const label=document.activeElement?.textContent;render(false);window.scrollTo(0,pos);const candidates=[...document.querySelectorAll(`[data-do="${a}"]`)];const b=candidates.find(x=>(!v||x.dataset.value===v)&&!x.disabled);if(b)b.focus({preventScroll:true});else if(isComplete(l.id,l.s))document.querySelector('[data-action="complete"]')?.focus({preventScroll:true});}
function action(a){switch(a){case 'language':state.lang=state.lang==='en'?'ur':'en';render(false);toast(state.lang==='ur'?'Roman Urdu titles on. Detailed practice instructions are in English.':'English selected.');break;case 'size':state.large=!state.large;render(false);break;case 'clear-search':state.query='';state.category='All topics';state.page='library';render(false);break;case 'hint':state.lesson.hints++;state.lesson.showHint=true;render(false);toast(getTask(state.lesson.id).hint);break;case 'read':readGuide();break;case 'restart':{const l=state.lesson;l.s=initialState(l.id,l.transfer);l.feedback='';render(false);toast('This attempt has restarted. Your earlier help requests still count.');break;}case 'complete':complete();break;case 'helper-start':startTask(state.helperTask);break;case 'copy-guide':copyGuide();break;case 'download-progress':downloadProgress();break;}}
function complete(){const l=state.lesson;if(!isComplete(l.id,l.s))return;state.records.push({id:l.id,transfer:l.transfer,hints:l.hints,at:new Date().toISOString()});save();if(!l.transfer){const note=l.note;startTask(l.id,true);state.lesson.note=note;render();}else {state.page='result';render();}}
function readGuide(){if(!('speechSynthesis'in window)){toast('Spoken guidance is unavailable in this browser. The full text is shown in your guide.');return;}const t=getTask(state.lesson.id);speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t.goal+' '+t.why+' '+t.steps.join('. '));u.lang='en-US';u.rate=.85;u.onerror=()=>toast('Audio is unavailable. You can read the same guidance on screen.');speechSynthesis.speak(u);toast('Reading the guide in English. You can stop audio in settings.');}
async function copyGuide(){const url=new URL(location.href);url.hash='guide='+encodeURIComponent(state.helperTask)+'&name='+encodeURIComponent(state.helperName)+'&note='+encodeURIComponent(state.helperNote);try{await navigator.clipboard.writeText(url.toString());toast('Learner link copied. The link includes your name and note.');}catch{modal('copy-link',url.toString());}}
function downloadProgress(){const report={app:'Samajh',generated:new Date().toISOString(),note:'Practice observations only; not a mastery assessment.',attempts:state.records.map(r=>({...r,task:getTask(r.id).title}))};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='samajh-my-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your practice summary has been downloaded.');}
let modalCleanup=null;
function closeModal(){modalCleanup?.();modalCleanup=null;const root=$('#overlay-root');root.innerHTML='';document.body.style.overflow='';$('#app').inert=false;if(state.lastFocus?.isConnected)state.lastFocus.focus({preventScroll:true});else $('#main')?.focus({preventScroll:true});}
function modal(type,extra=''){modalCleanup?.();modalCleanup=null;state.lastFocus=document.activeElement;let html='';let cls='';
 if(type==='welcome'){cls='welcome';html=`<div class="welcome-art">${art()}</div><span class="eyebrow">A little help. A lot more confidence.</span><h2 style="margin-top:13px">Hello. You belong here.</h2><p>No tech skills needed. Just bring one thing you’d like to learn.</p><div class="language-options"><button class="btn ${state.lang==='en'?'btn-subtle':'btn-secondary'}" data-welcome-lang="en">English</button><button class="btn ${state.lang==='ur'?'btn-subtle':'btn-secondary'}" data-welcome-lang="ur">Roman Urdu</button></div><button class="btn btn-primary" id="welcome-start">${tr('start')}${icon('arrow',19)}</button><button class="skip-welcome" id="welcome-skip">Skip this welcome</button><p class="micro" style="margin-top:6px">No account. No pressure. Always at your pace.</p>`;}
 if(type==='settings')html=`<h2>A space that works for you.</h2><p>Make Samajh a little more comfortable.</p>${setting('Larger text','Make labels and reading areas larger.','large',state.large)}${setting('Gentle motion','Turn decorative movement on or off.','motion',state.motion)}${setting('Remember my progress','Optional. Saves practice history on this browser until you erase it.','save',state.save)}<div class="setting-row"><div><strong>Reading language</strong><small>Task titles support English and Roman Urdu. Full guidance is currently English.</small></div><select id="settings-lang" class="text-field" style="width:150px"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ur" ${state.lang==='ur'?'selected':''}>Roman Urdu</option></select></div><button class="btn btn-secondary full" id="stop-audio" style="margin-top:20px">${icon('stop',17)}Stop spoken guidance</button><button class="link-btn" id="settings-clear" style="margin-top:12px">Clear learning history</button>`;
 if(type==='help')html=`<span class="icon-tile">${icon('heart',25)}</span><h2 style="margin-top:20px">We’ll take it one step at a time.</h2><p>1. Choose something you want to do.</p><p>2. Try it in our practice space. Nothing real changes.</p><p>3. Ask for a clue, or see a demonstration whenever you need.</p><p>4. Try a different view to explore what you’ve learned.</p><div class="notice">${icon('shield',21)}No real calls, files, messages, or accounts are used. Samajh cannot control other apps.</div><button class="btn btn-primary full" id="help-tasks" style="margin-top:22px">Find a task ${icon('arrow',18)}</button>`;
 if(type==='privacy')html=`<h2>Your practice. Your choice.</h2><p>You can use Samajh without an account. Practice uses fictional names, files, settings, and calls.</p><p>History stays in this visit unless you enable “Remember my progress”. Saved history is kept in your browser, not in a Samajh account. Clear it in settings.</p><p>We do not ask for contacts, camera, microphone, passwords, or banking access. “Read to me” uses your browser’s speech service, which may use an external service depending on your device.</p><p>Helper links include any first name and note you choose to put in the URL. Anyone with the link and site access can read them. Avoid private details.</p><p>Samajh includes no advertising or analytics scripts. The hosting provider may keep technical request logs. Fonts are served locally.</p>`;
 if(type==='about')html=`<h2>A little understanding travels far.</h2><p>Samajh is an original Build4Better prototype for adults unfamiliar with particular digital tasks. Age is not a measure of ability.</p><p>Eight working practice tasks teach concepts across meeting controls, files, forms, and privacy. Interfaces are fictional. Real Zoom, Google Meet, Canva, and phone settings may work differently.</p><p>Learning results are observations from this practice space, not certification. This version has no live AI, automatic app control, real workflow capture, user accounts, or server-side lesson storage.</p><p>AI assisted implementation and content drafting. No user study results or worldwide novelty claims are presented.</p>`;
 if(type==='context')html=`<h2>Practise the idea. Check your app.</h2><p>Our fictional meeting controls teach ideas shared by many apps. Exact button names and available features depend on the app, device, version, and meeting host.</p><p>Choose your actual app for official guidance:</p><div class="choice-row"><a class="btn btn-secondary" href="https://support.zoom.com/" target="_blank" rel="noopener noreferrer">Zoom support ${icon('arrow',15)}</a><a class="btn btn-secondary" href="https://support.google.com/meet/" target="_blank" rel="noopener noreferrer">Google Meet help ${icon('arrow',15)}</a></div><p class="micro" style="margin-top:20px">These external links open official support in a new tab. Samajh is not affiliated with those services.</p>`;
 if(type==='video')html=`<span class="eyebrow">A quick hello</span><h2 style="margin-top:12px">Small steps. Real confidence.</h2><video controls playsinline preload="metadata" poster="assets/video-poster.png"><source src="assets/hello-samajh.mp4" type="video/mp4"><track kind="captions" src="assets/intro.vtt" srclang="en" label="English" default>Your browser cannot play this video.</video><p class="video-caption"><strong>Video transcript:</strong> Choose something you want to do. Try it in a safe space. Understand what changes. Then give it a go on your own. No rush. No judgement.</p><button class="btn btn-primary full" id="video-start">Choose a task ${icon('arrow',18)}</button>`;
 if(type==='walkthrough'){const t=getTask(state.lesson.id);state.lesson.hints++;state.lesson.demonstrated=true;html=`<span class="eyebrow">A demonstration, at your pace</span><h2 style="margin-top:12px">${t.title}</h2><video controls playsinline preload="metadata" poster="assets/${t.id}-poster.png"><source src="assets/${t.id}-guide.mp4" type="video/mp4"><track kind="captions" src="assets/${t.id}-guide.vtt" srclang="en" label="English" default></video><p class="micro">A silent, captioned visual step guide. You can also move through the steps below.</p><div class="share-preview" id="demo-display"><div><span class="icon-tile" style="margin:auto">${icon(t.icon,30)}</span><h3 id="demo-text" style="margin-top:18px">${t.steps[0]}</h3><p class="micro" id="demo-counter" style="margin-top:10px">Step 1 of 3</p></div></div><p>${t.hint}</p><div class="choice-row"><button class="btn btn-secondary" id="demo-back">Previous step</button><button class="btn btn-subtle" id="demo-next">Next step ${icon('arrow',15)}</button></div><button class="btn btn-primary full" id="demo-return" style="margin-top:15px">Let me try</button><p class="micro" style="margin-top:12px">This demonstration counts as help in this attempt. That’s okay.</p>`;}
 if(type==='erase')html=`<h2>Clear your learning history?</h2><p>This removes your practice results from this visit and any saved results on this browser. You can start fresh.</p><div class="choice-row"><button class="btn btn-secondary" id="erase-cancel">Keep my history</button><button class="btn btn-primary" id="erase-confirm">Clear history</button></div>`;
 if(type==='copy-link')html=`<h2>Your learner link</h2><p>Copy this link manually. It includes the first name and note you provided.</p><textarea class="text-field" readonly>${esc(extra)}</textarea>`;
 $('#overlay-root').innerHTML=`<div class="modal-shade"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${type==='welcome'?'Welcome to Samajh':type==='video'?'Samajh introduction video':'Samajh '+type}"><button class="close-btn" aria-label="Close dialog">${icon('close',19)}</button>${html}</section></div>`;document.body.style.overflow='hidden';$('#app').inert=true;$('.close-btn').onclick=()=>{closeModal();if(type==='walkthrough')render(false);};$('.modal-shade').onclick=e=>{if(e.target.classList.contains('modal-shade'))closeModal();};
 const key=e=>{if(e.key==='Escape'){closeModal();}if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button:not(:disabled),a,input,select,textarea,video')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);modalCleanup=()=>{document.removeEventListener('keydown',key);$('#overlay-root video')?.pause();};$('.close-btn').focus();
 document.querySelectorAll('[data-welcome-lang]').forEach(b=>b.onclick=()=>{state.lang=b.dataset.welcomeLang;render(false);modal('welcome');});
 const start=()=>{try{sessionStorage.setItem('samajh-welcome','seen');}catch{}closeModal();};if($('#welcome-start'))$('#welcome-start').onclick=start;if($('#welcome-skip'))$('#welcome-skip').onclick=start;
 document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{const k=b.dataset.setting;state[k]=!state[k];save();render(false);modal('settings');});
 $('#settings-lang')?.addEventListener('change',e=>{state.lang=e.target.value;render(false);modal('settings');});
 if($('#stop-audio'))$('#stop-audio').onclick=()=>{window.speechSynthesis?.cancel();toast('Spoken guidance stopped.');};
 if($('#settings-clear'))$('#settings-clear').onclick=()=>modal('erase');
 if($('#erase-cancel'))$('#erase-cancel').onclick=closeModal;
 if($('#erase-confirm'))$('#erase-confirm').onclick=()=>{state.records=[];save();closeModal();render(false);toast('Learning history cleared.');};
 for(const id of ['help-tasks','video-start'])if($('#'+id))$('#'+id).onclick=()=>{closeModal();navigate('library');};
 if(type==='walkthrough'){let i=0;const t=getTask(state.lesson.id);const update=()=>{$('#demo-text').textContent=t.steps[i];$('#demo-counter').textContent=`Step ${i+1} of 3`;$('#demo-back').disabled=i===0;$('#demo-next').disabled=i===2;};$('#demo-back').onclick=()=>{i=Math.max(0,i-1);update();};$('#demo-next').onclick=()=>{i=Math.min(2,i+1);update();};$('#demo-return').onclick=()=>{closeModal();render(false);};update();}
}
function setting(label,desc,key,value){return `<div class="setting-row"><div><strong>${label}</strong><small>${desc}</small></div><button class="switch" role="switch" aria-checked="${value}" aria-label="${label}" data-setting="${key}"><span></span></button></div>`;}
function route(){const hash=location.hash.slice(1);if(hash.startsWith('task=')){const id=hash.slice(5);if(getTask(id)){startTask(id);return;}}if(hash.startsWith('guide=')){const params=new URLSearchParams(hash);const id=params.get('guide');if(getTask(id)){state.helperTask=id;state.helperName=(params.get('name')||'').slice(0,30);state.helperNote=(params.get('note')||'').slice(0,240);state.helperReady=true;startTask(id);return;}}if(['home','library','progress','helper'].includes(hash))state.page=hash;render(false);}
window.addEventListener('hashchange',route);route();let welcomeSeen=false;try{welcomeSeen=sessionStorage.getItem('samajh-welcome')==='seen';}catch{}if(!welcomeSeen&&!location.hash.startsWith('#guide='))modal('welcome');
